"use client";

import React, { useRef, useEffect } from "react";
import {
  motion,
  useMotionValue,
  useSpring,
  useTransform,
  MotionValue,
} from "framer-motion";

// Default high-quality sample images
const DEFAULT_IMAGES = [
  "https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?auto=format&fit=crop&w=1200&q=80",
  "https://images.unsplash.com/photo-1579783902614-a3fb3927b675?auto=format&fit=crop&w=1200&q=80",
  "https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=1200&q=80",
  "https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=1200&q=80",
  "https://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&w=1200&q=80",
];

export interface ImageLayerProps {
  src: string;
  index: number;
  total: number;
  progress: MotionValue<number>;
  alt?: string;
}

const ImageLayer: React.FC<ImageLayerProps> = ({
  src,
  index,
  total,
  progress,
  alt,
}) => {
  // Step bounds for each image in the scroll sequence
  const start = index / total;
  const end = (index + 1) / total;
  const peek = start + (end - start) * 0.15; // Point where initial flash reaches peak standard exposure

  // Y-translation: slide up from bottom into position
  const y = useTransform(progress, [start, peek], ["100%", "0%"]);

  // Brightness & Contrast flash effect on appearance
  const brightness = useTransform(
    progress,
    [start, start + 0.05, peek],
    [2.8, 2.2, 1.0] // High exposure burst -> softens -> normal brightness
  );

  const contrast = useTransform(
    progress,
    [start, start + 0.05, peek],
    [1.8, 1.4, 1.0] // High contrast flash -> normal contrast
  );

  // Combine motion values into CSS filter standard string
  const filter = useTransform(
    [brightness, contrast],
    ([b, c]) => `brightness(${b}) contrast(${c})`
  );

  // Opacity for entry handling
  const opacity = useTransform(progress, [start, start + 0.02], [0, 1]);

  return (
    <motion.div
      style={{
        y,
        opacity,
        filter,
        zIndex: index + 1,
      }}
      className="absolute inset-0 w-full h-full overflow-hidden bg-black flex items-center justify-center"
    >
      {/* Background Image */}
      <img
        src={src}
        alt={alt || `Reveal Image ${index + 1}`}
        className="w-full h-full object-cover grayscale select-none"
      />

      {/* SVG Grain Overlay - Recreates tactile noise effect per frame */}
      <div className="absolute inset-0 pointer-events-none opacity-45 mix-blend-overlay">
        <svg className="w-full h-full">
          <filter id={`grain-${index}`}>
            <feTurbulence
              type="fractalNoise"
              baseFrequency="0.80"
              numOctaves="3"
              stitchTiles="stitch"
            />
            <feColorMatrix type="saturate" values="0" />
          </filter>

          <rect
            width="100%"
            height="100%"
            filter={`url(#grain-${index})`}
          />
        </svg>
      </div>
    </motion.div>
  );
};

export interface ImageRevealProps {
  /** Array of image URLs to reveal in sequence */
  images?: string[];
  /** Fallback single image URL */
  src?: string;
  /** Fallback alt text */
  alt?: string;
  /** Enable mouse wheel scroll locking hook (default: true) */
  wheelHook?: boolean;
  /** Scroll sensitivity factor (higher = slower step per wheel click) */
  sensitivity?: number;
  /** Custom container class names */
  className?: string;
}

export function ImageReveal({
  images,
  src,
  alt,
  wheelHook = true,
  sensitivity = 600,
  className = "",
}: ImageRevealProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const rawProgress = useMotionValue(0);
  const progress = useSpring(rawProgress, { stiffness: 180, damping: 24 });

  const imageList =
    images && images.length > 0
      ? images
      : src
      ? [src]
      : DEFAULT_IMAGES;

  // Intercept wheel events to advance reveal progress without scrolling the window page
  useEffect(() => {
    if (!wheelHook) return;
    const element = containerRef.current;
    if (!element) return;

    const handleWheel = (e: WheelEvent) => {
      const current = rawProgress.get();
      const delta = e.deltaY / sensitivity;
      const next = Math.min(1, Math.max(0, current + delta));

      // Lock page scroll if scrolling down and not yet fully revealed (next < 1)
      // or scrolling up and not yet at start (next > 0)
      if (
        (e.deltaY > 0 && current < 0.999) ||
        (e.deltaY < 0 && current > 0.001)
      ) {
        e.preventDefault();
        e.stopPropagation();
        rawProgress.set(next);
      }
    };

    element.addEventListener("wheel", handleWheel, { passive: false });
    return () => {
      element.removeEventListener("wheel", handleWheel);
    };
  }, [rawProgress, wheelHook, sensitivity]);

  const promptOpacity = useTransform(progress, [0, 0.08], [1, 0]);

  return (
    <div
      ref={containerRef}
      className={`relative w-full h-screen bg-black text-white flex flex-col items-center justify-center overflow-hidden select-none ${className}`}
    >
      {/* Introductory Scroll Prompt */}
      <motion.div
        style={{ opacity: promptOpacity }}
        className="absolute z-0 flex flex-col items-center justify-center text-center space-y-3 pointer-events-none"
      >
        <p className="text-xs uppercase tracking-[0.3em] font-mono text-neutral-400">
          Scroll Down
          <br />
          To Reveal
          <br />
          The Images
        </p>
        <div className="w-[1px] h-12 bg-neutral-600" />
      </motion.div>

      {/* Framed Display Area */}
      <div className="relative w-[85%] max-w-4xl aspect-[4/3] sm:aspect-[16/10] overflow-hidden border border-neutral-800 shadow-2xl z-10">
        {imageList.map((imgSrc, index) => (
          <ImageLayer
            key={index}
            src={imgSrc}
            index={index}
            total={imageList.length}
            progress={progress}
            alt={alt}
          />
        ))}
      </div>
    </div>
  );
}

export default ImageReveal;
